MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    if ((dds_info->mipmap_count > 1) && (IsTexture(dds_info) || IsCubeMap(dds_info))) {
        MagickSizeType offset = 0;
        MagickSizeType width = image->columns;
        MagickSizeType height = image->rows;

        for (size_t level = 1; level < dds_info->mipmap_count; level++) {
            MagickSizeType level_width = width / 2;
            MagickSizeType level_height = height / 2;
            MagickSizeType level_size = level_width * level_height * pixel_size;
            if (SeekBlob(image, offset + level_size, SEEK_SET) == -1) {
                return MagickFalse;
            }
            offset += level_size;
            width = level_width;
            height = level_height;
        }
    }
    return MagickTrue;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  if ((dds_info->mipmap_count > 0) && ((dds_info->texture) || (dds_info->cube_map))) {
    MagickSizeType width = image->columns;
    MagickSizeType height = image->rows;
    MagickSizeType row_size = width * pixel_size;
    MagickSizeType image_size = row_size * height;
    MagickBooleanType status = MagickTrue;

    for (MagickSizeType level = 1; level < dds_info->mipmap_count; level++) {
      MagickSizeType new_width = (MagickSizeType) ceil(width / 2.0);
      MagickSizeType new_height = (MagickSizeType) ceil(height / 2.0);
      MagickSizeType new_row_size = new_width * pixel_size;
      MagickSizeType new_image_size = new_row_size * new_height;

      if (SeekBlob(image, image_size, SEEK_CUR) != (MagickSizeType)(image_size)) {
        status = MagickFalse;
        break;
      }

      width = new_width;
      height = new_height;
      image_size = new_image_size;
    }

    return status;
  }

  return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmapImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  register ssize_t
    x;

  size_t
    length;

  ssize_t
    count;

  if ((dds_info->flags & (HasMipmaps | Texture | CubeMap)) != (HasMipmaps | Texture) && (dds_info->flags & (HasMipmaps | CubeMap)) != (HasMipmaps | CubeMap))
    return(MagickTrue);

  for (x=image->rows >> 1; x > 0; x >>= 1) {
    length=(size_t) pixel_size*x*image->columns;
    count=SeekBlob(image,length,SEEK_CUR);
    if ((size_t) count != length)
      return(MagickFalse);
  }

  return(MagickTrue);
}

MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  register ssize_t y;
  size_t row_size;
  MagickBooleanType status = MagickTrue;

  if ((dds_info->mipmap_count > 1) && ((dds_info->flags & DDS_TEXTURE) || (dds_info->flags & DDS_CUBEMAP))) {
    for (y = 1; y < (ssize_t) dds_info->mipmap_count; y++) {
      image->columns >>= 1;
      image->rows >>= 1;
      if (image->columns == 0)
        image->columns = 1;
      if (image->rows == 0)
        image->rows = 1;
      row_size = (size_t) pixel_size * image->columns;
      if (SeekImageBlob(image, row_size * image->rows) != (OffT) (row_size * image->rows))
        status = MagickFalse;
    }
  }

  return status;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    MagickBooleanType status = MagickTrue;
    size_t width = image->columns;
    size_t height = image->rows;
    size_t level;

    if ((dds_info->mipmap_count > 1) && (IsTextureOrCubeMap(dds_info))) {
        for (level = 1; level < dds_info->mipmap_count; level++) {
            size_t skip_size = width * height * pixel_size;
            if (SeekImagePixels(image, skip_size, SEEK_CUR, exception) != skip_size) {
                status = MagickFalse;
                break;
            }
            width = (width >> 1) ? (width >> 1) : 1;
            height = (height >> 1) ? (height >> 1) : 1;
        }
    }

    return status;
}
